const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.468626, -45.432798]);
  const roi = point.buffer(100000); // 100km radius

  const period1_start = '2018-11-01';
  const period1_end = '2019-02-28';
  const period2_start = '2019-11-01';
  const period2_end = '2020-02-29';

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .select('chlor_a');

  const col1 = collection
    .filterDate(period1_start, period1_end)
    .filterBounds(roi);

  const col2 = collection
    .filterDate(period2_start, period2_end)
    .filterBounds(roi);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Period 1 (Nov 2018-Feb 2019) Images: ${size1}`);
  console.log(`Period 2 (Nov 2019-Feb 2020) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("One or both periods have no images.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites
  const img1 = col1.mean();
  const img2 = col2.mean();

  // 4. Calculation with pixel count validation
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = await img1.reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await img2.reduceRegion({
    reducer: reducer,
    geometry: roi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1['chlor_a_mean'];
  const count1 = stats1['chlor_a_count'];
  const mean2 = stats2['chlor_a_mean'];
  const count2 = stats2['chlor_a_count'];

  console.log(`Period 1: Mean=${mean1}, Pixels=${count1}`);
  console.log(`Period 2: Mean=${mean2}, Pixels=${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 == null || mean2 == null || isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if values are in reasonable range (chlorophyll-a typically 0.01-100 mg/m³)
  if (mean1 < 0 || mean1 > 200 || mean2 < 0 || mean2 > 200) {
    console.log("Values out of reasonable range for chlorophyll.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Chlorophyll change: ${((mean2 - mean1) / mean1 * 100).toFixed(2)}%`);

  if (mean2 > mean1) {
    console.log("Chlorophyll concentrations were UP in 2019-2020 vs 2018-2019.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Chlorophyll concentrations were NOT up in 2019-2020 vs 2018-2019.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
